const parseNestedParens = (paren_string) => {
  const groups = paren_string.trim().split(/\s+/);
  const results = [];

  for (const group of groups) {
    if (group === '') continue;
    let currentDepth = 0;
    let maxDepth = 0;
    for (const char of group) {
      if (char === '(') {
        currentDepth++;
        if (currentDepth > maxDepth) {
          maxDepth = currentDepth;
        }
      } else if (char === ')') {
        currentDepth--;
      }
    }
    results.push(maxDepth);
  }

  return results;
};

